import { isEstimateOrMiscellaneousTransaction } from '../shared/estimateScreeningPolicy';

export type CalculationTone = 'activity' | 'spend_proxy' | 'estimate';

type ToneSource = {
  metadata?: { carbonInputBasis?: string };
  carbonFootprint?: {
    quantificationMethod?: string;
    calculationMethod?: string;
    dataQualityTier?: string;
    factorLineage?: { id?: string } | null;
    factorId?: string;
    complianceFlags?: string[] | Record<string, boolean>;
  };
  quantificationMethod?: string;
  calculationMethod?: string;
  dataQualityTier?: string;
  factorLineage?: { id?: string } | null;
  factorId?: string;
  complianceFlags?: string[] | Record<string, boolean>;
};

const ACTIVITY_METHODS = new Set([
  'activity_based',
  'supplier_primary',
  'ocr_consumption_activity',
]);

const SPEND_METHODS = new Set(['spend_proxy', 'spend-proxy', 'tier_2_spend']);

export const CALCULATION_TONE_STYLE: Record<CalculationTone, {
  chipColor: 'success' | 'warning' | 'error';
  background: string;
  label: string;
}> = {
  activity: {
    chipColor: 'success',
    background: 'rgba(46, 125, 50, 0.14)',
    label: 'Activity-based',
  },
  spend_proxy: {
    chipColor: 'warning',
    background: 'rgba(237, 108, 2, 0.16)',
    label: 'Spend proxy',
  },
  estimate: {
    chipColor: 'error',
    background: 'rgba(211, 47, 47, 0.14)',
    label: 'Estimate',
  },
};

const footprintOf = (source: ToneSource = {}) => (
  source.carbonFootprint && typeof source.carbonFootprint === 'object'
    ? source.carbonFootprint
    : source
);

export const resolveCalculationTone = (source: ToneSource = {}): CalculationTone | null => {
  const footprint = footprintOf(source);
  const method = String(footprint.quantificationMethod || footprint.calculationMethod || '').toLowerCase();
  const tier = String(footprint.dataQualityTier || '').toLowerCase();
  const factorId = String(footprint.factorLineage?.id || footprint.factorId || '');
  const transaction = source.carbonFootprint ? source : { carbonFootprint: footprint, metadata: source.metadata };
  const estimate = isEstimateOrMiscellaneousTransaction(transaction);

  if (
    factorId === 'spend_generic'
    || estimate.reason === 'miscellaneous_factor'
    || method === 'estimate'
  ) {
    return 'estimate';
  }
  if (ACTIVITY_METHODS.has(method) || tier === 'tier_1_activity') {
    return 'activity';
  }
  if (tier === 'tier_3_estimate') {
    return 'estimate';
  }
  if (
    SPEND_METHODS.has(method)
    || tier === 'tier_2_spend_proxy'
    || estimate.reason === 'estimate_spend_proxy'
  ) {
    return 'spend_proxy';
  }
  return null;
};

export const tierChipColor = (tier?: string | null): 'success' | 'warning' | 'error' | 'default' => {
  if (tier === 'tier_1_activity') return 'success';
  if (tier === 'tier_2_spend_proxy') return 'warning';
  if (tier === 'tier_3_estimate') return 'error';
  return 'default';
};
